import 'server-only'
import { createAdminClient } from '@/lib/supabase/admin'
import type { EventQrToken, EventStaff, QrTokenKind } from '@/modules/event-management/types/event'

/**
 * Staff assignment + QR token management (server-side, org-scoped).
 *
 * event_qr_tokens is the single source of truth for BOTH staff and booth
 * tokens. The token is an opaque value generated by the database default
 * (`encode(gen_random_bytes(32), 'base64url')`) — no personal data is ever
 * placed in a QR URL. Tokens are soft-revoked (status), never hard-deleted.
 */

async function assertEventInOrg(orgId: string, eventId: string): Promise<boolean> {
  const admin = createAdminClient() as any
  const { data } = await admin
    .from('event_events')
    .select('id')
    .eq('id', eventId)
    .eq('organization_id', orgId)
    .maybeSingle()
  return Boolean(data)
}

const STAFF_SELECT = `
  id, event_id, user_id, created_at,
  users:user_id(full_name, email)
`

function shapeStaff(row: any): EventStaff {
  const user = Array.isArray(row.users) ? row.users[0] : row.users
  return { ...row, full_name: user?.full_name ?? null, email: user?.email ?? null } as EventStaff
}

export async function listStaff(orgId: string, eventId: string): Promise<EventStaff[]> {
  if (!(await assertEventInOrg(orgId, eventId))) return []
  const admin = createAdminClient() as any
  const { data, error } = await admin
    .from('event_staff')
    .select(STAFF_SELECT)
    .eq('event_id', eventId)
    .order('created_at', { ascending: true })

  if (error) throw new Error(error.message)
  return (data ?? []).map(shapeStaff)
}

export async function assignStaff(orgId: string, eventId: string, userId: string): Promise<EventStaff | null> {
  if (!(await assertEventInOrg(orgId, eventId))) return null
  const admin = createAdminClient() as any

  // The assigned user must belong to the same organization.
  const user = await admin.from('users').select('id, organization_id').eq('id', userId).maybeSingle()
  if (!user.data || user.data.organization_id !== orgId) return null

  const { data, error } = await admin
    .from('event_staff')
    .upsert({ event_id: eventId, user_id: userId }, { onConflict: 'event_id,user_id' })
    .select(STAFF_SELECT)
    .single()

  if (error) throw new Error(error.message)
  return data ? shapeStaff(data) : null
}

export async function removeStaff(orgId: string, eventId: string, userId: string): Promise<boolean> {
  if (!(await assertEventInOrg(orgId, eventId))) return false
  const admin = createAdminClient() as any

  // Soft-revoke the staff's active QRs before removing the assignment, so
  // historical attribution is preserved (tokens never hard-deleted).
  await admin
    .from('event_qr_tokens')
    .update({ status: 'revoked' })
    .eq('event_id', eventId)
    .eq('staff_user_id', userId)
    .eq('kind', 'staff')
    .eq('status', 'active')

  const { error } = await admin
    .from('event_staff')
    .delete()
    .eq('event_id', eventId)
    .eq('user_id', userId)

  return !error
}

const TOKEN_SELECT = `
  id, event_id, staff_user_id, token, kind, status, created_at, created_by,
  users:staff_user_id(full_name)
`

function shapeToken(row: any): EventQrToken {
  const user = Array.isArray(row.users) ? row.users[0] : row.users
  return { ...row, staff_name: user?.full_name ?? null } as EventQrToken
}

export async function listQrTokens(orgId: string, eventId: string): Promise<EventQrToken[]> {
  if (!(await assertEventInOrg(orgId, eventId))) return []
  const admin = createAdminClient() as any
  const { data, error } = await admin
    .from('event_qr_tokens')
    .select(TOKEN_SELECT)
    .eq('event_id', eventId)
    .order('created_at', { ascending: true })

  if (error) throw new Error(error.message)
  return (data ?? []).map(shapeToken)
}

export async function createQrToken(
  orgId: string,
  eventId: string,
  kind: QrTokenKind,
  staffUserId: string | null,
  createdBy: string,
): Promise<EventQrToken> {
  if (!(await assertEventInOrg(orgId, eventId))) throw new Error('Event not found.')

  const admin = createAdminClient() as any

  if (kind === 'staff') {
    if (!staffUserId) throw new Error('A staff member is required for a staff QR.')
    // The staff member must be assigned to this event AND belong to this org.
    const assigned = await admin
      .from('event_staff')
      .select('id, user_id, users:user_id(organization_id)')
      .eq('event_id', eventId)
      .eq('user_id', staffUserId)
      .maybeSingle()
    const staffOrg = Array.isArray(assigned.data?.users)
      ? assigned.data.users[0]?.organization_id
      : assigned.data?.users?.organization_id
    if (!assigned.data || staffOrg !== orgId) {
      throw new Error('Staff is not assigned to this event.')
    }
    // One ACTIVE staff QR per (event, staff): revoke any existing active staff QR first.
    await admin
      .from('event_qr_tokens')
      .update({ status: 'revoked' })
      .eq('event_id', eventId)
      .eq('staff_user_id', staffUserId)
      .eq('kind', 'staff')
      .eq('status', 'active')
  } else {
    // One ACTIVE booth QR per event: revoke any existing active booth QR first.
    await admin
      .from('event_qr_tokens')
      .update({ status: 'revoked' })
      .eq('event_id', eventId)
      .eq('kind', 'booth')
      .eq('status', 'active')
    staffUserId = null
  }

  const { data, error } = await admin
    .from('event_qr_tokens')
    .insert({ event_id: eventId, kind, staff_user_id: staffUserId, created_by: createdBy })
    .select(TOKEN_SELECT)
    .single()

  if (error) throw new Error(error.message)
  return shapeToken(data)
}

export async function revokeQrToken(orgId: string, eventId: string, tokenId: string): Promise<boolean> {
  if (!(await assertEventInOrg(orgId, eventId))) return false
  const admin = createAdminClient() as any
  const { error } = await admin
    .from('event_qr_tokens')
    .update({ status: 'revoked' })
    .eq('id', tokenId)
    .eq('event_id', eventId)
    .eq('status', 'active')

  return !error
}

/** Public, server-side token resolution via the service-role-only RPC. */
export async function validateEventToken(token: string): Promise<any | null> {
  const admin = createAdminClient() as any
  const { data, error } = await admin.rpc('validate_event_qr_token', { p_token: token })
  if (error) return null
  return data ?? null
}

